import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator, StatusBar, StyleSheet } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { useFonts, PlusJakartaSans_400Regular, PlusJakartaSans_500Medium, PlusJakartaSans_600SemiBold, PlusJakartaSans_700Bold, PlusJakartaSans_800ExtraBold } from '@expo-google-fonts/plus-jakarta-sans';
import Toast from 'react-native-toast-message';
import { AppProviders } from './src/providers/AppProviders';
import { RootNavigator } from './src/presentation/navigation/RootNavigator';
import { useAuthStore } from './src/shared/stores/useAuthStore';
import { useThemeStore } from './src/shared/stores/useThemeStore';
import { useLanguageStore } from './src/shared/stores/useLanguageStore';
import { AppColors } from './src/presentation/theme/colors';
import { seedAll } from './src/data/storage/seedData';

export default function App() {
  const [fontsLoaded] = useFonts({
    PlusJakartaSans_400Regular,
    PlusJakartaSans_500Medium,
    PlusJakartaSans_600SemiBold,
    PlusJakartaSans_700Bold,
    PlusJakartaSans_800ExtraBold,
  });

  const [isDbReady, setIsDbReady] = useState(false);

  const initAuth = useAuthStore((s) => s.initAuth);
  const initTheme = useThemeStore((s) => s.initTheme);
  const initLocale = useLanguageStore((s) => s.initLocale);

  useEffect(() => {
    (async () => {
      try {
        // Khß╗ƒi tß║ío stores
        initAuth();
        initTheme();
        initLocale();
        // Seed dß╗» liß╗çu mock v├áo SQLite (idempotent)
        await seedAll();
      } catch (e) {
        if (__DEV__) {
          console.warn('[App] Init error:', e);
        }
      } finally {
        setIsDbReady(true);
      }
    })();
  }, []);

  if (!fontsLoaded || !isDbReady) {
    return (
      <View style={styles.loading}>
        <ActivityIndicator size="large" color={AppColors.primary} />
      </View>
    );
  }

  return (
    <AppProviders>
      <NavigationContainer>
        <RootNavigator />
        <StatusBar barStyle="dark-content" />
      </NavigationContainer>
      <Toast />
    </AppProviders>
  );
}

const styles = StyleSheet.create({
  loading: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: AppColors.lightBackground,
  },
});

/**
 * Jest setup - mock c├íc module native kh├┤ng chß║íy ─æ╞░ß╗úc trong m├┤i tr╞░ß╗¥ng Node
 *
 * Theo P0.6d: mock react-native-mmkv, expo-sqlite, expo-localization
 */

jest.mock('react-native-mmkv', () => ({
  MMKV: jest.fn(() => {
    const store = new Map();
    return {
      getString: (k) => store.get(k),
      set: (k, v) => store.set(k, v),
      delete: (k) => store.delete(k),
      contains: (k) => store.has(k),
      getAllKeys: () => Array.from(store.keys()),
      clearAll: () => store.clear(),
    };
  }),
}));

jest.mock('expo-sqlite', () => ({
  openDatabaseAsync: jest.fn(),
}));

jest.mock('expo-localization', () => ({
  getLocales: () => [{ languageCode: 'vi' }],
}));

/**
 * ApiClient - HTTP client d├╣ng chung cho to├án bß╗Ö Real*Service
 *
 * Port tß╗½: Web/src/utils/axios.js (─æ├ú chß║íy production) + Mobile/lib/data/services/dio_client.dart
 *
 * 8 Bß║«T BUß╗ÿC (P0.3):
 *   1. Response unwrap theo 3 nh├ính
 *   2. Ph├ón loß║íi lß╗ùi mß║íng vs lß╗ùi server (ApiException.isNetworkError)
 *   3. `skipAuth` cho endpoint public (kh├┤ng gß║»n Bearer)
 *   4. Refresh token single-flight (isRefreshing + failedQueue)
 *   5. Retry giß╗» nguy├¬n config gß╗æc (method/data/headers/params)
 *   6. 401 tß║íi endpoint AUTH -> KH├öNG refresh, KH├öNG logout
 *   7. Refresh token hß║┐t hß║ín theo config ─æß╗Öng (─æß╗ìc expiresAt tß╗½ BE)
 *   8. KH├öNG hardcode bß║Ñt kß╗│ gi├í trß╗ï BE ─æ├ú l├ám dynamic
 */

import axios from 'axios';
import { appConfig } from '../../shared/config/appConfig';
import { TokenStorage } from '../storage/TokenStorage';
import { ApiException } from './ApiException';

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Event emitter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Screens nghe 'session-expired' ─æß╗â ─æ╞░a user vß╗ü m├án Login.

const listeners = new Map();

export const onApiEvent = (event, handler) => {
  if (!listeners.has(event)) listeners.set(event, new Set());
  listeners.get(event).add(handler);
  return () => {
    listeners.get(event)?.delete(handler);
  };
};

const emitApiEvent = (event, payload) => {
  listeners.get(event)?.forEach((handler) => {
    try {
      handler(payload);
    } catch (e) {
      if (__DEV__) console.warn(`[ApiClient] listener lß╗ùi cho "${event}":`, e);
    }
  });
};

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Instance ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const client = axios.create({
  baseURL: appConfig.API_BASE_URL,
  timeout: appConfig.TIMEOUT_MS,
  headers: { 'Content-Type': 'application/json' },
});

// Client gß╗æc, KH├öNG qua interceptor - d├╣ng ─æß╗â gß╗ìi /auth/refresh tr├ính loop v├┤ hß║ín
const rawClient = axios.create({
  baseURL: appConfig.API_BASE_URL,
  timeout: appConfig.TIMEOUT_MS,
  headers: { 'Content-Type': 'application/json' },
});

// Bß║«T BUß╗ÿC 6: 401 ß╗ƒ c├íc endpoint n├áy = sai th├┤ng tin ─æ─âng nhß║¡p (sai mß║¡t khß║⌐u,
// email sai, OTP sai), KH├öNG phß║úi hß║┐t phi├¬n. Source: commit BE 70aa944.
const SKIP_AUTH_REFRESH_ENDPOINTS = [
  '/auth/email/login',
  '/auth/email/register',
  '/auth/email/verify-otp',
  '/auth/email/forgot-password',
  '/auth/email/reset-password',
  '/auth/google',
  '/auth/phone/send-otp',
  '/auth/phone/verify',
];

const isAuthEndpoint = (url = '') => SKIP_AUTH_REFRESH_ENDPOINTS.some((path) => url.includes(path));

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Bß║«T BUß╗ÿC 4: single-flight ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
  failedQueue.forEach(({ resolve, reject }) => {
    if (error) reject(error);
    else resolve(token);
  });
  failedQueue = [];
};

/** X├│a token + b├ío cho app biß║┐t phi├¬n hß║┐t hß║ín */
const handleSessionExpired = () => {
  TokenStorage.clearAll();
  emitApiEvent('session-expired');
};

/**
 * Bß║«T BUß╗ÿC 7: suy ra thß╗¥i ─æiß╗âm hß║┐t hß║ín tß╗½ response BE.
 * ╞»u ti├¬n `expiresAt` BE trß║ú vß╗ü -> fallback decode JWT payload `exp`.
 * TUYß╗åT ─Éß╗ÉI kh├┤ng hardcode 7 ng├áy (BE ─æ├ú chuyß╗ân sang config ─æß╗Öng).
 */
const extractExpiry = (token) => {
  if (!token || typeof token !== 'string') return undefined;
  const parts = token.split('.');
  if (parts.length !== 3) return undefined;
  try {
    const payload = JSON.parse(
      typeof atob === 'function'
        ? atob(parts[1].replace(/-/g, '+').replace(/_/g, '/'))
        : Buffer.from(parts[1], 'base64').toString('utf8')
    );
    if (payload?.exp) return payload.exp * 1000; // gi├óy -> ms
  } catch (e) {
    // token kh├┤ng phß║úi JWT hoß║╖c decode lß╗ùi -> bß╗Å qua, kh├┤ng chß║╖n luß╗ông
  }
  return undefined;
};

/**
 * L╞░u access + refresh token mß╗¢i k├¿m thß╗¥i ─æiß╗âm hß║┐t hß║ín.
 *
 * Bß║«T BUß╗ÿC 7/8 - thß╗⌐ tß╗▒ ╞░u ti├¬n:
 *   1. `expiresAt` / `accessExpiresAt` BE trß║ú vß╗ü  -> lu├┤n d├╣ng
 *   2. `expiresIn` (gi├óy) BE trß║ú vß╗ü             -> quy ─æß╗òi tß╗½ thß╗¥i ─æiß╗âm hiß╗çn tß║íi
 *   3. decode JWT payload `exp`                  -> khi BE kh├┤ng trß║ú field n├áo
 *   4. ACCESS_TTL_FALLBACK_SECONDS               -> cuß╗æi c├╣ng, CHß╗ê ─æß╗â app kh├┤ng vß╗í
 *
 * Mß╗Ñc 4 KH├öNG phß║úi "gi├í trß╗ï ─æ├║ng": nß║┐u admin ─æß╗òi `token.accessTtl` tr├¬n BE,
 * BE sß║╜ trß║ú `expiresAt`/`expiresIn` n├¬n nh├ính 1-2 ─æ╞░ß╗úc d├╣ng v├á gi├í trß╗ï n├áy kh├┤ng bao giß╗¥ chß║ím tß╗¢i.
 */
const persistTokens = (data) => {
  if (!data) return;

  const now = Date.now();

  if (data.accessToken) {
    TokenStorage.setAccessToken(data.accessToken);
  }
  if (data.refreshToken) {
    TokenStorage.setRefreshToken(data.refreshToken);
  }

  const accessExpiresAt =
    data.accessExpiresAt ??
    data.expiresAt ??
    (data.expiresIn !== undefined && data.expiresIn !== null
      ? now + Number(data.expiresIn) * 1000
      : undefined) ??
    extractExpiry(data.accessToken) ??
    now + ACCESS_TTL_FALLBACK_SECONDS * 1000;

  const refreshExpiresAt = data.refreshExpiresAt ?? extractExpiry(data.refreshToken) ?? undefined;

  TokenStorage.setTokenExpiry({ accessExpiresAt, refreshExpiresAt });
};

// Bß║«T BUß╗ÿC 8: hß║▒ng sß╗æ fallback CHß╗ê d├╣ng khi BE kh├┤ng trß║ú field n├áo.
// Kh├┤ng phß║úi "gi├í trß╗ï ─æ├║ng" - sß║╜ sai nß║┐u admin ─æß╗òi config tr├¬n BE.
const ACCESS_TTL_FALLBACK_SECONDS = 900;

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Bß║«T BUß╗ÿC 1 + 3: interceptors ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

client.interceptors.request.use(
  (config) => {
    // Bß║«T BUß╗ÿC 3: endpoint public -> kh├┤ng gß║»n Bearer
    if (config.skipAuth) return config;

    const token = TokenStorage.getAccessToken();
    if (token) {
      config.headers = config.headers || {};
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

client.interceptors.response.use(
  // ΓöÇΓöÇ Bß║«T BUß╗ÿC 1: unwrap 3 nh├ính ΓöÇΓöÇ
  (response) => {
    const body = response.data;

    // Nh├ính 1: c├│ `data` kh├íc null -> trß║ú thß║│ng `data`
    if (body && typeof body === 'object' && 'data' in body && body.data !== null) {
      return body.data;
    }

    // Nh├ính 2: `success: true` -> trß║ú `data` (c├│ thß╗â null = hß╗úp lß╗ç, v├¡ dß╗Ñ xo├í th├ánh c├┤ng)
    if (body && typeof body === 'object' && body.success === true) {
      return body.data ?? null;
    }

    // Nh├ính 3: `success: false` -> lß╗ùi d├╣ HTTP 200
    if (body && typeof body === 'object' && body.success === false) {
      return Promise.reject(
        new ApiException(body.message || 'Thao t├íc thß║Ñt bß║íi', {
          statusCode: response.status,
          data: body,
          isNetworkError: false,
        })
      );
    }

    // Kh├┤ng c├│ wrapper n├áo khß╗¢p -> trß║ú nguy├¬n body (endpoint trß║ú thß║│ng)
    return body;
  },

  async (error) => {
    const originalRequest = error?.config;
    const status = error?.response?.status;

    // ΓöÇΓöÇ Bß║«T BUß╗ÿC 6 + 4: xß╗¡ l├╜ 401 ΓöÇΓöÇ
    if (status === 401 && originalRequest && !originalRequest._retry) {
      // 401 ß╗ƒ endpoint AUTH = sai th├┤ng tin ─æ─âng nhß║¡p -> trß║ú lß╗ùi cho form, KH├öNG refresh
      if (originalRequest.skipAuthRefresh || isAuthEndpoint(originalRequest.url)) {
        return Promise.reject(ApiException.fromAxiosError(error));
      }

      // 401 ß╗ƒ /auth/refresh = hß║┐t phi├¬n chß║»c chß║»n
      if (originalRequest.url?.includes('/auth/refresh')) {
        handleSessionExpired();
        return Promise.reject(
          new ApiException('Phi├¬n ─æ─âng nhß║¡p ─æ├ú hß║┐t hß║ín. Vui l├▓ng ─æ─âng nhß║¡p lß║íi!', {
            statusCode: 401,
          })
        );
      }

      // ─Éang refresh -> request n├áy xß║┐p h├áng chß╗¥ (Bß║«T BUß╗ÿC 4)
      if (isRefreshing) {
return new Promise((resolve, reject) => {
            failedQueue.push({ resolve, reject });
          })
          .then((token) => {
            // Bß║«T BUß╗ÿC 5: giß╗» nguy├¬n method/data/params cß╗ºa request gß╗æc
            originalRequest.headers = originalRequest.headers || {};
            originalRequest.headers.Authorization = `Bearer ${token}`;
            return client.request(originalRequest);
          })
          .catch((err) => Promise.reject(err));
      }

      originalRequest._retry = true;
      isRefreshing = true;

      const refreshToken = TokenStorage.getRefreshToken();

      if (!refreshToken || TokenStorage.isRefreshTokenExpired()) {
        isRefreshing = false;
        const expiredErr = new ApiException('Phi├¬n ─æ─âng nhß║¡p ─æ├ú hß║┐t hß║ín. Vui l├▓ng ─æ─âng nhß║¡p lß║íi!', {
          statusCode: 401,
        });
        processQueue(expiredErr, null);
        handleSessionExpired();
        return Promise.reject(expiredErr);
      }

      try {
        // rawClient: KH├öNG qua interceptor -> kh├┤ng loop v├┤ hß║ín
        const refreshResponse = await rawClient.request({
          method: 'post',
          url: '/auth/refresh',
          data: { refreshToken },
          headers: { 'Content-Type': 'application/json' },
        });

        // Bß║«T BUß╗ÿC 1: ├íp dß╗Ñng c├╣ng quy tß║»c unwrap
        const resData = refreshResponse.data?.data ?? refreshResponse.data;
        const newAccessToken = resData?.accessToken;

        if (!newAccessToken) {
          throw new Error('Kh├┤ng lß║Ñy ─æ╞░ß╗úc Access Token mß╗¢i');
        }

        persistTokens(resData);

        client.defaults.headers.common.Authorization = `Bearer ${newAccessToken}`;

        // Bß║«T BUß╗ÿC 5: giß╗» nguy├¬n config gß╗æc khi replay
        originalRequest.headers = originalRequest.headers || {};
        originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;

        processQueue(null, newAccessToken);
        return client.request(originalRequest);
      } catch (refreshErr) {
        const expiredErr = new ApiException('Phi├¬n ─æ─âng nhß║¡p ─æ├ú hß║┐t hß║ín. Vui l├▓ng ─æ─âng nhß║¡p lß║íi!', {
          statusCode: 401,
        });
        processQueue(expiredErr, null);
        handleSessionExpired();
        return Promise.reject(expiredErr);
      } finally {
        isRefreshing = false;
      }
    }

    return Promise.reject(ApiException.fromAxiosError(error));
  }
);

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Public API ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Gß╗ìi GET/POST/PATCH/PUT/DELETE.
 * @param {string} url
 * @param {object} [options]
 * @param {boolean} [options.skipAuth] - endpoint public, kh├┤ng gß║»n Bearer
 * @param {boolean} [options.skipAuthRefresh] - 401 ß╗ƒ endpoint n├áy l├á lß╗ùi form, kh├┤ng refresh
 */
const request = async (method, url, data, options = {}) => {
  const config = { ...options };
  if (data !== undefined && method !== 'get' && method !== 'delete') {
    config.data = data;
  }
  return client.request({ ...config, method, url });
};

export const ApiClient = {
  client,
  onApiEvent,

  get: (url, options) => request('get', url, undefined, options),
  post: (url, data, options) => request('post', url, data, options),
  patch: (url, data, options) => request('patch', url, data, options),
  put: (url, data, options) => request('put', url, data, options),
  delete: (url, options) => request('delete', url, undefined, options),

  /**
   * Upload file qua FormData (avatar, scan ß║únh/receipt).
   * @param {string} url
   * @param {string} uri - URI cß╗Ñc bß╗Ö cß╗ºa file
   * @param {string} [fieldName='file']
   * @param {object} [formFields] - c├íc field text k├¿m theo
   */
  uploadFile: async (url, uri, fieldName = 'file', formFields = {}) => {
    const formData = new FormData();
    formData.append(fieldName, {
      uri,
      name: uri.split('/').pop() || 'upload',
      type: 'image/jpeg',
    });
    Object.entries(formFields).forEach(([key, value]) => {
      if (value !== undefined && value !== null) formData.append(key, String(value));
    });

    // KH├öNG set Content-Type thß╗º c├┤ng - axios/FormData phß║úi tß╗▒ set boundary
    return client.request({
      method: 'post',
      url,
      data: formData,
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },

  /** D├╣ng cho c├íc flow ─æß║╖c biß╗çt cß║ºn gß╗ìi trß╗▒c tiß║┐p (vd: OAuth, streaming) */
  raw: rawClient,
};

export default ApiClient;

/**
 * Mock axios cho test - kiß╗âm so├ít thß╗º c├┤ng instance + interceptor
 *
 * `axios.create()` trß║ú lß║ºn l╞░ß╗út 2 instance:
 *   1. mainClient (c├│ interceptor request/response)
 *   2. rawClient  (kh├┤ng interceptor - d├╣ng cho /auth/refresh)
 */

const makeMockClient = () => {
  const interceptors = { request: null, response: null };
  return {
    defaults: { headers: { common: {} } },
    interceptors: {
      request: {
        use: (fulfilled, rejected) => {
          interceptors.request = { fulfilled, rejected };
        },
      },
      response: {
        use: (fulfilled, rejected) => {
          interceptors.response = { fulfilled, rejected };
        },
      },
    },
    request: jest.fn(),
    __interceptors: interceptors,
    __reset: () => {
      interceptors.request = null;
      interceptors.response = null;
      this.defaults.headers.common = {};
      this.request.mockReset();
    },
  };
};

// Biß║┐n chia sß║╗: test ─æß╗ìc ─æß╗â chß║íy interceptor bß║▒ng tay
const instances = [];

const axios = {
  create: jest.fn(() => {
    const client = makeMockClient();
    instances.push(client);
    return client;
  }),
  get: jest.fn(),
  post: jest.fn(),
