/**
 * TokenStorage - Quß║ún l├╜ token + user data trong MMKV
 *
 * Port tß╗½ Flutter: Mobile/lib/config/app_constants.dart (4 storage keys)
 * Bß╗ò sung sau merge BE 21/10 (commit 43f0103): 2 keys hß║┐t hß║ín ─æß╗Öng.
 *
 * Storage keys PHß║óI giß╗æng hß╗çt Flutter ─æß╗â Flutter/RN ─æß╗ìc chung ─æ╞░ß╗úc data:
 *   access_token, refresh_token, user_id, user_data
 *
 * Keys mß╗¢i (optional - app vß║½n chß║íy nß║┐u thiß║┐u):
 *   token_expires_at, refresh_expires_at
 */

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  // Fallback in-memory khi MMKV ch╞░a load (test, web, ch╞░a rebuild native)
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
    contains: (k) => memStore[k] !== undefined,
    delete: (k) => {
      delete memStore[k];
    },
  };
}

const KEYS = {
  ACCESS_TOKEN: 'access_token',
  REFRESH_TOKEN: 'refresh_token',
  USER_ID: 'user_id',
  USER_DATA: 'user_data',
  TOKEN_EXPIRES_AT: 'token_expires_at',
  REFRESH_EXPIRES_AT: 'refresh_expires_at',
};

/** Buffer 60s: coi token l├á hß║┐t hß║ín sß╗¢m h╞ín ─æß╗â tr├ính hß║┐t hß║ín giß╗»a chß╗½ng request */
const EXPIRY_BUFFER_MS = 60 * 1000;

const readString = (key) => {
  try {
    const v = mmkv.getString(key);
    return v === undefined || v === null ? null : v;
  } catch (e) {
    return null;
  }
};

const writeString = (key, value) => {
  try {
    mmkv.set(key, value);
  } catch (e) {
    // ignore - storage lß╗ùi kh├┤ng ─æ╞░ß╗úc l├ám crash app
  }
};

const removeKey = (key) => {
  try {
    mmkv.delete(key);
  } catch (e) {
    // ignore
  }
};

export const TokenStorage = {
  KEYS,

  // ---------- Access token ----------
  getAccessToken: () => readString(KEYS.ACCESS_TOKEN),
  setAccessToken: (token) => writeString(KEYS.ACCESS_TOKEN, token),

  // ---------- Refresh token ----------
  getRefreshToken: () => readString(KEYS.REFRESH_TOKEN),
  setRefreshToken: (token) => writeString(KEYS.REFRESH_TOKEN, token),

  // ---------- User ----------
  getUserId: () => readString(KEYS.USER_ID),
  setUserId: (id) => writeString(KEYS.USER_ID, String(id)),

  getUserData: () => {
    const raw = readString(KEYS.USER_DATA);
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch (e) {
      return null;
    }
  },
  setUserData: (user) => {
    if (!user) {
      removeKey(KEYS.USER_DATA);
      return;
    }
    writeString(KEYS.USER_DATA, JSON.stringify(user));
  },

  // ---------- Expiry ─æß╗Öng (sau merge BE 21/10) ----------
  /**
   * L╞░u thß╗¥i ─æiß╗âm hß║┐t hß║ín cß╗ºa cß║ú 2 token.
   * @param {{accessExpiresAt?: number, refreshExpiresAt?: number}} expiry - timestamp (ms)
   */
  setTokenExpiry: ({ accessExpiresAt, refreshExpiresAt } = {}) => {
    if (accessExpiresAt !== undefined && accessExpiresAt !== null) {
      writeString(KEYS.TOKEN_EXPIRES_AT, String(accessExpiresAt));
    }
    if (refreshExpiresAt !== undefined && refreshExpiresAt !== null) {
      writeString(KEYS.REFRESH_EXPIRES_AT, String(refreshExpiresAt));
    }
  },

  /** @returns {number|null} timestamp (ms), null nß║┐u ch╞░a c├│ -> coi nh╞░ ch╞░a hß║┐t hß║ín */
  getAccessExpiresAt: () => {
    const raw = readString(KEYS.TOKEN_EXPIRES_AT);
    return raw === null ? null : Number(raw);
  },

  /** @returns {number|null} timestamp (ms), null nß║┐u ch╞░a c├│ */
  getRefreshExpiresAt: () => {
    const raw = readString(KEYS.REFRESH_EXPIRES_AT);
    return raw === null ? null : Number(raw);
  },

  /**
   * Access token c├▓n hß║ín kh├┤ng? C├│ buffer 60s.
   * Ch╞░a c├│ th├┤ng tin hß║┐t hß║ín -> coi nh╞░ CH╞»A hß║┐t hß║ín (─æß╗â app vß║½n chß║íy).
   */
  isAccessTokenExpired: () => {
    const exp = TokenStorage.getAccessExpiresAt();
    if (exp === null || Number.isNaN(exp)) return false;
    return Date.now() >= exp - EXPIRY_BUFFER_MS;
  },

  /** Refresh token c├▓n hß║ín kh├┤ng? C├│ buffer 60s. */
  isRefreshTokenExpired: () => {
    const exp = TokenStorage.getRefreshExpiresAt();
    if (exp === null || Number.isNaN(exp)) return false;
    return Date.now() >= exp - EXPIRY_BUFFER_MS;
  },

  // ---------- Session ----------
  /**
   * ─É├║ng logic Flutter: chß╗ë kiß╗âm tra access_token c├│ v├á kh├┤ng rß╗ùng.
   * KH├öNG kiß╗âm tra hß║┐t hß║ín ß╗ƒ ─æ├óy - ApiClient lo phß║ºn ─æ├│.
   */
  isLoggedIn: () => {
    const token = TokenStorage.getAccessToken();
    return !!token && token.length > 0;
  },

  /** X├│a Cß║ó 6 keys trong 1 lß║ºn */
  clearAll: () => {
    Object.values(KEYS).forEach(removeKey);
  },
};

export default TokenStorage;

/**
 * Seed Data Helper
 *
 * Khi app lß║ºn ─æß║ºu chß║íy, kiß╗âm tra nß║┐u SQLite rß╗ùng th├¼ import dß╗» liß╗çu
 * tß╗½ mock JSON. Sau n├áy sß║╜ thay bß║▒ng sync tß╗½ API.
 */

import databaseService from './DatabaseService';
import userMock from '../../shared/mocks/user.json';
import inventoryMock from '../../shared/mocks/inventory.json';
import summaryMock from '../../shared/mocks/fridge-summary.json';
import preferencesMock from '../../shared/mocks/user-preferences.json';
import allergiesMock from '../../shared/mocks/allergies.json';
import familyMock from '../../shared/mocks/family-members.json';
import notificationsMock from '../../shared/mocks/notifications.json';
import shoppingMock from '../../shared/mocks/shopping-reminder.json';
import weeklyStatsMock from '../../shared/mocks/weekly-stats.json';

/**
 * Check xem database ─æ├ú c├│ data ch╞░a
 */
const isTableEmpty = async (table) => {
  const result = await databaseService.queryOne(`SELECT COUNT(*) as count FROM ${table}`);
  return result.count === 0;
};

const safeJsonStringify = (obj) => JSON.stringify(obj);

/**
 * Seed users
 */
const seedUsers = async () => {
  if (!(await isTableEmpty('users'))) return;
  await databaseService.insert('users', {
    id: userMock.id,
    name: userMock.name,
    email: userMock.email,
    phone: userMock.phone || null,
    avatar: userMock.avatar || null,
    birthday: null,
    gender: null,
    bio: null,
    join_date: userMock.joinDate,
    is_family_plan: userMock.isFamilyPlan ? 1 : 0,
  });
};

/**
 * Seed fridge items
 */
const seedFridgeItems = async () => {
  if (!(await isTableEmpty('fridge_items'))) return;
  for (const item of inventoryMock.items) {
    await databaseService.insert('fridge_items', {
      id: item.id,
      name: item.name,
      category: item.category,
      quantity: item.quantity,
      unit: item.unit,
      expiry_date: item.expiryDate,
      status: item.status,
      image: item.image || null,
      compartment: 'fridge',
    });
  }
};

/**
 * Seed fridge stats
 */
const seedFridgeStats = async () => {
  if (!(await isTableEmpty('fridge_stats'))) return;
  await databaseService.insert('fridge_stats', {
    id: 1,
    expired_count: summaryMock.expiredCount,
    available_count: summaryMock.availableCount,
  });
};

/**
 * Seed user preferences
 */
const seedPreferences = async () => {
  if (!(await isTableEmpty('user_preferences'))) return;
  await databaseService.insert('user_preferences', {
    id: 1,
    diet: preferencesMock.preferences.diet,
    spice_level: preferencesMock.preferences.spiceLevel,
    cooking_time: preferencesMock.preferences.cookingTime,
    servings: preferencesMock.preferences.servings,
  });
};

/**
 * Seed allergies
 */
const seedAllergies = async () => {
  if (!(await isTableEmpty('allergies'))) return;
  for (const a of allergiesMock.allergies) {
    await databaseService.insert('allergies', {
      id: a.id,
      name: a.name,
      severity: a.severity,
    });
  }
};

/**
 * Seed family members
 */
const seedFamily = async () => {
  if (!(await isTableEmpty('family_members'))) return;
  for (const m of familyMock.members) {
    await databaseService.insert('family_members', {
      id: m.id,
      name: m.name,
      role: m.role,
      avatar: m.avatar || null,
    });
  }
};

/**
 * Seed notifications
 */
const seedNotifications = async () => {
  if (!(await isTableEmpty('notifications'))) return;
  for (const n of notificationsMock.notifications) {
    await databaseService.insert('notifications', {
      id: n.id,
      type: n.type,
      title: n.title,
      message: n.message,
      time: n.time,
      read: n.read ? 1 : 0,
    });
  }
};

/**
 * Seed shopping items
 */
const seedShopping = async () => {
  if (!(await isTableEmpty('shopping_items'))) return;
  for (const item of shoppingMock.items) {
    await databaseService.insert('shopping_items', {
      id: item.id,
      name: item.name,
      quantity: item.quantity,
      unit: item.unit,
      done: item.done ? 1 : 0,
    });
  }
};

/**
 * Seed weekly stats
 */
const seedWeeklyStats = async () => {
  if (!(await isTableEmpty('weekly_stats'))) return;
  await databaseService.insert('weekly_stats', {
    id: 1,
    week_data: safeJsonStringify({
      week: weeklyStatsMock.week,
      data: weeklyStatsMock.data,
    }),
    total: weeklyStatsMock.total,
    previous_week: weeklyStatsMock.previousWeek,
  });
};

/**
 * Seed tß║Ñt cß║ú dß╗» liß╗çu mock v├áo SQLite.
 * Idempotent - chß╗ë seed khi table rß╗ùng.
 */
export const seedAll = async () => {
  await databaseService.init();
  await Promise.all([
    seedUsers(),
    seedFridgeItems(),
    seedFridgeStats(),
    seedPreferences(),
    seedAllergies(),
    seedFamily(),
    seedNotifications(),
    seedShopping(),
    seedWeeklyStats(),
  ]);
  if (__DEV__) {
    console.log('[Seed] Mock data ─æ├ú ─æ╞░ß╗úc import v├áo SQLite (nß║┐u DB rß╗ùng)');
  }
};

