      const result = {};
      for (const t of tables) {
        const r = await databaseService.queryOne(`SELECT COUNT(*) as count FROM ${t}`);
        result[t] = r.count;
      }
      setCounts(result);
      setDbStatus('connected');
    } catch (e) {
      setDbStatus('error: ' + e.message);
    }
  };

  const testServices = async () => {
    setTesting(true);
    setTestResult(null);
    try {
      const fridge = await services.fridgeService.getItems();
      const summary = await services.fridgeService.getSummary();
      const recipes = await services.recipeService.getRecipes();
      const stats = await services.recipeService.getWeeklyStats();
      const notifs = await services.notificationService.getNotifications();
      const profile = await services.userService.getProfile();
      const plan = await services.userService.getCurrentPlan();

      setTestResult({
        fridgeCount: fridge.length,
        summary,
        recipesCount: recipes.length,
        stats,
        notifsCount: notifs.length,
        profile: profile.name,
        plan: plan.displayName,
      });
    } catch (e) {
      setTestResult({ error: e.message });
    } finally {
      setTesting(false);
    }
  };

  return (
    <View
      style={[
        styles.container,
        {
          backgroundColor: isDark ? colors.darkSurface : colors.lightSurface,
          borderColor: isDark ? colors.darkCardBorder : colors.border,
        },
      ]}
    >
      <Text style={[styles.title, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
        Sprint 1 Debug
      </Text>

      <Text style={[styles.label, { color: isDark ? colors.darkTextSecondary : colors.textSecondary }]}>
        Database: {dbStatus}
      </Text>

      {Object.keys(counts).length > 0 && (
        <View style={styles.countsBlock}>
          {Object.entries(counts).map(([t, c]) => (
            <Text
              key={t}
              style={[styles.countText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}
            >
              {t}: {c} rows
            </Text>
          ))}
        </View>
      )}

      <TouchableOpacity
        style={[styles.button, { backgroundColor: colors.primary }]}
        onPress={testServices}
        disabled={testing}
      >
        {testing ? (
          <ActivityIndicator size="small" color="#fff" />
        ) : (
          <Text style={styles.buttonText}>Test Services</Text>
        )}
      </TouchableOpacity>

      {testResult && (
        <View style={styles.resultBlock}>
          {testResult.error ? (
            <Text style={[styles.resultText, { color: colors.error }]}>Error: {testResult.error}</Text>
          ) : (
            <>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Fridge items: {testResult.fridgeCount}
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Summary: {testResult.summary.expiredCount} expired, {testResult.summary.availableCount} available
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Recipes: {testResult.recipesCount}
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Weekly total: {testResult.stats.total}
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Notifications: {testResult.notifsCount}
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Profile: {testResult.profile}
              </Text>
              <Text style={[styles.resultText, { color: isDark ? colors.darkTextPrimary : colors.textPrimary }]}>
                Plan: {testResult.plan}
              </Text>
            </>
          )}
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    margin: sp(16),
    padding: sp(16),
    borderRadius: sp(12),
    borderWidth: 1,
  },
  title: {
    fontSize: sp(18),
    fontWeight: '800',
    marginBottom: sp(8),
  },
  label: {
    fontSize: sp(13),
    marginBottom: sp(8),
  },
  countsBlock: {
    marginBottom: sp(12),
  },
  countText: {
    fontSize: sp(12),
    marginVertical: sp(2),
  },
  button: {
    paddingVertical: sp(10),
    borderRadius: sp(8),
    alignItems: 'center',
    marginBottom: sp(12),
  },
  buttonText: {
    color: '#fff',
    fontWeight: '700',
    fontSize: sp(14),
  },
  resultBlock: {
    gap: sp(4),
  },
  resultText: {
    fontSize: sp(12),
  },
});

/**
 * FridgeItem
 *
 * Row hiß╗ân thß╗ï 1 nguy├¬n liß╗çu trong tß╗º lß║ính:
 * - Icon (theo category: vegetable/meat/dairy/fruit/other)
 * - Name + quantity
 * - Expiry badge vß╗¢i m├áu sß║»c (fresh: xanh, expiring: cam, expired: ─æß╗Å)
 * - Press handler
 */

import React from 'react';
import { View, Text, Pressable, Image, StyleSheet } from 'react-native';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontFamily, FontWeights } from '../../theme/typography';
import { AlertCircle, Carrot, Beef, Egg, Apple, Leaf } from 'lucide-react-native';
import { useTranslation } from 'react-i18next';

const CATEGORY_ICON = {
  vegetable: Carrot,
  meat: Beef,
  dairy: Egg,
  fruit: Apple,
  other: Leaf,
};

const CATEGORY_COLOR = {
  vegetable: '#4CAF50',
  meat: '#E57373',
  dairy: '#FFB300',
  fruit: '#FF7043',
  other: '#9E9E9E',
};

const STATUS_COLOR = {
  fresh: { bg: '#E8F5E9', fg: '#1B5E20', darkBg: '#1B3324', darkFg: AppColors.primaryLight },
  expiring: { bg: '#FFF3E0', fg: '#E65100', darkBg: '#3D2E1A', darkFg: '#FFB74D' },
  expired: { bg: '#FFEBEE', fg: '#B71C1C', darkBg: '#3D1F1A', darkFg: '#FF8A80' },
};

const getDaysToExpiry = (expiryDate) => {
  const expiry = new Date(expiryDate);
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  expiry.setHours(0, 0, 0, 0);
  return Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
};

const formatExpiry = (days, isEn) => {
  if (days < 0) return isEn ? 'Expired' : '─É├ú hß║┐t hß║ín';
  if (days === 0) return isEn ? 'Today' : 'H├┤m nay';
  if (days === 1) return isEn ? 'Tomorrow' : 'Ng├áy mai';
  return isEn ? `${days}d` : `${days} ng├áy`;
};

const IMAGE_MAP = {
  food_tomato: require('../../../../assets/images/food_tomato.png'),
  food_milk: require('../../../../assets/images/food_milk.png'),
  food_pork: require('../../../../assets/images/food_pork.png'),
  food_bokchoy: require('../../../../assets/images/food_bokchoy.png'),
};

export const FridgeItem = ({ item, onPress, style }) => {
  const { isDark } = useTheme();
  const { t, i18n } = useTranslation();
  const isEn = i18n.language === 'en';

  const Icon = CATEGORY_ICON[item.category] || Leaf;
  const iconColor = CATEGORY_COLOR[item.category] || CATEGORY_COLOR.other;
  const days = getDaysToExpiry(item.expiryDate);
  const status = item.status || (days < 0 ? 'expired' : days <= 3 ? 'expiring' : 'fresh');
  const colorScheme = STATUS_COLOR[status];
  const badgeBg = isDark ? colorScheme.darkBg : colorScheme.bg;
  const badgeFg = isDark ? colorScheme.darkFg : colorScheme.fg;

  const imageSource = item.image && IMAGE_MAP[item.image] ? IMAGE_MAP[item.image] : null;

  return (
    <Pressable
      onPress={() => onPress && onPress(item)}
      style={({ pressed }) => [
        {
          opacity: pressed ? 0.85 : 1,
        },
        style,
      ]}
    >
      <View
        style={[
          styles.row,
          {
            backgroundColor: isDark ? '#19271E' : '#F4F7F4',
            borderColor: status === 'expiring' || status === 'expired'
              ? badgeFg
              : 'transparent',
            borderWidth: status === 'expiring' || status === 'expired' ? 1 : 0,
          },
        ]}
      >
        <View
          style={[
            styles.iconWrap,
            { backgroundColor: iconColor + (isDark ? '33' : '22') },
          ]}
        >
          {imageSource ? (
            <Image source={imageSource} style={styles.image} resizeMode="contain" />
          ) : (
            <Icon color={iconColor} size={22} strokeWidth={2.2} />
          )}
        </View>
        <View style={{ flex: 1, marginLeft: sp(12) }}>
          <Text
            style={[
              styles.name,
              { color: isDark ? '#FFFFFF' : AppColors.textPrimary },
            ]}
            numberOfLines={1}
          >
            {item.name}
          </Text>
          <Text
            style={[
              styles.qty,
              { color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary },
            ]}
            numberOfLines={1}
          >
            {item.quantity} {item.unit}
          </Text>
        </View>
        <View style={[styles.badge, { backgroundColor: badgeBg }]}>
          {status === 'expired' || status === 'expiring' ? (
            <AlertCircle color={badgeFg} size={11} strokeWidth={2.5} />
          ) : null}
          <Text
            style={[
              styles.badgeText,
              { color: badgeFg, marginLeft: status !== 'fresh' ? sp(3) : 0 },
            ]}
          >
            {formatExpiry(days, isEn)}
          </Text>
        </View>
      </View>
    </Pressable>
  );
};

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: sp(14),
    borderRadius: sp(14),
  },
  iconWrap: {
    width: sp(44),
    height: sp(44),
    borderRadius: sp(12),
    alignItems: 'center',
    justifyContent: 'center',
  },
  image: {
    width: sp(36),
    height: sp(36),
  },
  name: {
    fontSize: sp(15),
    fontFamily: FontFamily.semibold,
    fontWeight: FontWeights.semibold,
  },
  qty: {
    fontSize: sp(12),
    fontFamily: FontFamily.regular,
    marginTop: sp(2),
  },
  badge: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: sp(8),
    paddingVertical: sp(4),
    borderRadius: sp(10),
  },
  badgeText: {
    fontSize: sp(11),
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
  },
});

