      <LinearGradient
        colors={bannerColors}
        locations={stops}
        start={{ x: 0.5, y: 0 }}
        end={{ x: 0.5, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />
      <View style={[styles.glow, { backgroundColor: glowColor }]} />
      <View style={styles.mascotWrap}>
        <Image
          source={imageAsset}
          style={styles.mascot}
          resizeMode="contain"
        />
      </View>
      <View style={styles.textWrap}>
        <Text
          style={[
            styles.greetingLabel,
            { color: greetingColor, fontSize: sp(12) },
