        </Text>
        <Text
          style={[
            styles.name,
            { color: textColorPrimary, fontSize: sp(28) },
          ]}
          numberOfLines={1}
        >
          {firstName}
        </Text>
        <Text
          style={[
            styles.desc,
            { color: textColorSecondary, fontSize: sp(13) },
          ]}
          numberOfLines={2}
        >
          {t('home.readyToHelpShort')}
