/**
 * AiChatScreen
 *
 * Redesigned (Sprint 7):
 * - MessageBubble component (t├ích tß╗½ inline code)
 * - Suggestion chips khi mß╗¢i mß╗ƒ (gß╗úi ├╜ c├óu hß╗Åi)
 * - Animated typing indicator (3 dots fade in/out)
 * - Avatar cho AI (Bot icon) v├á user (User icon)
 * - Smart reply generator vß╗¢i pattern matching th├┤ng minh h╞ín
 * - Pull-down to clear chat
 * - Auto-scroll to bottom khi c├│ tin nhß║»n mß╗¢i
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TextInput,
  Pressable,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontWeights, FontFamily } from '../../theme/typography';
import { useTranslation } from 'react-i18next';
import { Send, Bot, User, Sparkles } from 'lucide-react-native';
import { showInfo } from '../../utils/helpers';
import { MessageBubble } from '../../components/chat/MessageBubble';

const AIAvatar = () => {
  return (
    <View style={[styles.avatar, { backgroundColor: AppColors.primary }]}>
      <Bot color="#FFFFFF" size={16} strokeWidth={2.2} />
    </View>
  );
};

const UserAvatar = () => {
  const { isDark } = useTheme();
  return (
    <View
      style={[
        styles.avatar,
        {
          backgroundColor: isDark ? '#233629' : AppColors.accentGreen,
        },
      ]}
    >
      <User
        color={isDark ? AppColors.primaryLight : AppColors.forestAccent}
        size={16}
      />
    </View>
  );
};

const TypingIndicator = ({ isDark }) => {
  const opacity1 = useRef(new Animated.Value(0.3)).current;
  const opacity2 = useRef(new Animated.Value(0.3)).current;
  const opacity3 = useRef(new Animated.Value(0.3)).current;

  useEffect(() => {
    const animations = [
      Animated.loop(
        Animated.sequence([
          Animated.timing(opacity1, { toValue: 1, duration: 400, useNativeDriver: true }),
          Animated.timing(opacity1, { toValue: 0.3, duration: 400, useNativeDriver: true }),
        ]),
      ),
      Animated.loop(
        Animated.sequence([
          Animated.delay(200),
          Animated.timing(opacity2, { toValue: 1, duration: 400, useNativeDriver: true }),
          Animated.timing(opacity2, { toValue: 0.3, duration: 400, useNativeDriver: true }),
        ]),
      ),
      Animated.loop(
        Animated.sequence([
          Animated.delay(400),
          Animated.timing(opacity3, { toValue: 1, duration: 400, useNativeDriver: true }),
          Animated.timing(opacity3, { toValue: 0.3, duration: 400, useNativeDriver: true }),
        ]),
      ),
    ];
    animations.forEach((a) => a.start());
    return () => animations.forEach((a) => a.stop());
  }, [opacity1, opacity2, opacity3]);

  return (
    <View
      style={[
        styles.bubble,
        styles.aiBubble,
        {
          backgroundColor: isDark ? '#19271E' : '#FFFFFF',
          borderColor: isDark ? '#2E4D36' : '#A5E69C',
        },
      ]}
    >
      <View style={styles.thinkingDots}>
        <Animated.View style={[styles.dot, { backgroundColor: AppColors.primary, opacity: opacity1 }]} />
        <Animated.View style={[styles.dot, { backgroundColor: AppColors.primary, opacity: opacity2 }]} />
        <Animated.View style={[styles.dot, { backgroundColor: AppColors.primary, opacity: opacity3 }]} />
      </View>
    </View>
  );
};

const now = () => {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
};

const generateReply = (input, t) => {
  const lower = input.toLowerCase();
  if (lower.includes('trß╗⌐ng') || lower.includes('egg')) {
    return 'Vß╗¢i trß╗⌐ng trong tß╗º lß║ính, bß║ín c├│ thß╗â l├ám: Trß╗⌐ng x├áo c├á chua, Trß╗⌐ng chi├¬n, Trß╗⌐ng luß╗Öc, hoß║╖c Trß╗⌐ng cuß╗Ön rau. Bß║ín muß╗æn c├┤ng thß╗⌐c chi tiß║┐t kh├┤ng?';
  }
  if (lower.includes('c├á chua') || lower.includes('tomato')) {
    return 'C├á chua rß║Ñt tß╗æt cho sß╗⌐c khß╗Åe! Bß║ín c├│ thß╗â nß║Ñu: Canh c├á chua, C├á chua x├áo trß╗⌐ng, Salad c├á chua. M├│n n├áo bß║ín th├¡ch nhß║Ñt?';
  }
  if (lower.includes('gß╗úi ├╜') || lower.includes('cook') || lower.includes('nß║Ñu') || lower.includes('today')) {
    return 'Dß╗▒a tr├¬n tß╗º lß║ính cß╗ºa bß║ín, t├┤i gß╗úi ├╜ 3 m├│n:\n1. Trß╗⌐ng x├áo c├á chua (15 ph├║t)\n2. Canh rau cß╗º (25 ph├║t)\n3. Thß╗ït heo kho trß╗⌐ng (45 ph├║t)\nBß║ín th├¡ch m├│n n├áo?';
  }
  if (lower.includes('bß║úo quß║ún') || lower.includes('store')) {
    return 'Mß║╣o bß║úo quß║ún:\nΓÇó Rau cß╗º: rß╗¡a sß║ích, lau kh├┤, cho v├áo hß╗Öp k├¡n, ─æß╗â ng─ân m├ít 3-5 ng├áy\nΓÇó Thß╗ït: chia phß║ºn nhß╗Å, g├│i k├¡n, cß║Ñp ─æ├┤ng\nΓÇó Sß╗»a: ─æß╗â ng─ân m├ít, uß╗æng trong 5-7 ng├áy sau mß╗ƒ';
  }
  if (lower.includes('calo') || lower.includes('calorie')) {
    return 'M├│n ─ân ├¡t calo gß╗úi ├╜:\nΓÇó Canh rau cß╗º (~80 calo/b├ít)\nΓÇó Salad c├á chua d╞░a chuß╗Öt (~60 calo)\nΓÇó Trß╗⌐ng luß╗Öc (~78 calo/quß║ú)\nBß║ín muß╗æn c├┤ng thß╗⌐c chi tiß║┐t?';
  }
  return 'T├┤i hiß╗âu bß║ín ─æang hß╗Åi vß╗ü "' + input + '". T├┤i sß║╜ t├¼m c├┤ng thß╗⌐c ph├╣ hß╗úp vß╗¢i nguy├¬n liß╗çu trong tß╗º lß║ính. Bß║ín cho t├┤i biß║┐t th├¬m chi tiß║┐t nh├⌐!';
};

export const AiChatScreen = () => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const [messages, setMessages] = useState(() => [
    { id: 1, sender: 'ai', text: t('home.aiWelcome'), time: now() },
  ]);
  const [input, setInput] = useState('');
  const [thinking, setThinking] = useState(false);
  const scrollRef = useRef(null);

  const suggestionKeys = ['aiSug1', 'aiSug2', 'aiSug3', 'aiSug4'];

  useEffect(() => {
    setTimeout(() => {
      scrollRef.current?.scrollToEnd({ animated: true });
    }, 100);
  }, [messages, thinking]);

  const send = useCallback(
    (text) => {
      const messageText = (text ?? input).trim();
      if (!messageText) return;
      const userMsg = { id: Date.now(), sender: 'user', text: messageText, time: now() };
      setMessages((prev) => [...prev, userMsg]);
      setInput('');
      setThinking(true);
      setTimeout(() => {
        const reply = generateReply(messageText, t);
        setMessages((prev) => [
          ...prev,
          { id: Date.now() + 1, sender: 'ai', text: reply, time: now() },
        ]);
        setThinking(false);
      }, 1200);
    },
    [input, t],
  );

  const handleSuggestion = useCallback(
    (key) => {
      send(t('home.' + key));
    },
    [send, t],
  );

  const clearChat = useCallback(() => {
    setMessages([{ id: Date.now(), sender: 'ai', text: t('home.aiWelcome'), time: now() }]);
    showInfo(t('home.aiClearChat'));
  }, [t]);

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      style={[
        styles.container,
        { backgroundColor: isDark ? '#0E1611' : AppColors.accentGreen },
      ]}
    >
      <LinearGradient
        colors={isDark ? ['#0E1611', '#142017'] : ['#FFFFFF', '#F5FCF4', '#C7EFC2']}
        start={{ x: 0.5, y: 0 }}
        end={{ x: 0.5, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />

      {/* Header */}
      <View style={styles.header}>
        <AIAvatarLarge />
        <View style={{ flex: 1, marginLeft: 12 }}>
          <Text
            style={[
              styles.headerTitle,
              { color: isDark ? '#FFFFFF' : AppColors.textPrimary, fontSize: sp(17) },
            ]}
          >
            {t('home.aiTitle')}
          </Text>
          <View style={styles.statusRow}>
            <View style={styles.onlineDot} />
            <Text
              style={[
                styles.headerStatus,
                {
                  color: isDark ? AppColors.primaryLight : AppColors.forestAccent,
                  fontSize: sp(12),
                },
              ]}
            >
              {t('home.aiOnline')}
            </Text>
          </View>
        </View>
        <Pressable
          onPress={clearChat}
          hitSlop={8}
          style={({ pressed }) => [{ opacity: pressed ? 0.6 : 1 }]}
        >
          <Sparkles
            color={isDark ? AppColors.darkTextSecondary : AppColors.textSecondary}
            size={20}
          />
        </Pressable>
      </View>

      <ScrollView
        ref={scrollRef}
        style={styles.messages}
        contentContainerStyle={{ padding: 16, paddingBottom: 16 }}
        showsVerticalScrollIndicator={false}
      >
        {messages.map((m) => (
          <MessageBubble
            key={m.id}
            message={m}
            avatar={m.sender === 'ai' ? AIAvatar : UserAvatar}
            showAvatar
          />
        ))}

        {thinking ? <TypingIndicator isDark={isDark} /> : null}

        {/* Suggestion chips (chß╗ë hiß╗ân thß╗ï khi mß╗¢i mß╗ƒ) */}
        {messages.length === 1 && !thinking ? (
          <View style={styles.suggestionsBlock}>
            <Text
              style={[
                styles.suggestionsTitle,
                { color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary, fontSize: sp(12) },
              ]}
            >
              {t('home.aiSuggestions')}
            </Text>
            <View style={styles.suggestionsWrap}>
              {suggestionKeys.map((k) => (
                <Pressable
                  key={k}
                  onPress={() => handleSuggestion(k)}
                  style={({ pressed }) => [
                    styles.suggestionChip,
                    {
                      backgroundColor: isDark ? '#19271E' : '#FFFFFF',
                      borderColor: isDark ? '#2E4D36' : '#A5E69C',
                      opacity: pressed ? 0.8 : 1,
                    },
                  ]}
                >
                  <Text
                    style={[
                      styles.suggestionText,
                      { color: isDark ? AppColors.primaryLight : AppColors.forestAccent, fontSize: sp(12) },
                    ]}
                  >
                    {t('home.' + k)}
                  </Text>
                </Pressable>
              ))}
            </View>
          </View>
        ) : null}
      </ScrollView>

      <View
        style={[
          styles.inputBar,
          {
            backgroundColor: isDark ? '#0E1611' : '#FFFFFF',
            borderTopColor: isDark ? '#2E4D36' : '#E3E8E4',
          },
        ]}
      >
        <TextInput
          value={input}
          onChangeText={setInput}
          placeholder={t('home.aiAskPlaceholder')}
          placeholderTextColor={AppColors.hintText}
          style={[
            styles.input,
            { color: isDark ? '#FFFFFF' : AppColors.textPrimary, fontSize: sp(15) },
          ]}
          multiline
        />
        <Pressable
          onPress={() => send()}
          disabled={!input.trim()}
          style={({ pressed }) => [
            styles.sendBtn,
            {
              backgroundColor: AppColors.primary,
              opacity: !input.trim() ? 0.5 : pressed ? 0.85 : 1,
            },
          ]}
        >
          <Send color="#FFFFFF" size={20} strokeWidth={2.2} />
        </Pressable>
      </View>
    </KeyboardAvoidingView>
  );
};

const AIAvatarLarge = () => (
