/**
 * LoginScreen
 *
 * Redesigned (Sprint 6):
 * - Animated entrance (fade in + slide up) cho card
 * - i18n ─æß║ºy ─æß╗º cho success messages, social login labels
 * - Improved form validation vß╗¢i better error messages
 */

import React, { useState, useCallback, useEffect, useRef } from 'react';
import {
  View,
  Text,
  ScrollView,
  KeyboardAvoidingView,
  Platform,
  StyleSheet,
  Dimensions,
  Image,
  Pressable,
  StatusBar,
  Animated,
  Easing,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp, sw, sh } from '../../utils/responsive';
import { FontWeights, FontFamily } from '../../theme/typography';
import { useNavigation } from '@react-navigation/native';
import { useTranslation } from 'react-i18next';
import { Mail, Lock, Eye, EyeOff, ChevronLeft } from 'lucide-react-native';
import { CustomTextField } from '../../components/common/CustomTextField';
import { CustomButton } from '../../components/common/CustomButton';
import { CustomCheckbox } from '../../components/common/CustomCheckbox';
import { CustomDivider } from '../../components/common/CustomDivider';
import { SocialButton } from '../../components/common/SocialButton';
import { Routes } from '../../../shared/constants/routes';
import { isValidEmail, isValidPassword } from '../../utils/validators';
import { useAuthStore } from '../../../shared/stores/useAuthStore';
import { showSuccess } from '../../utils/helpers';
import userMock from '../../../shared/mocks/user.json';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

export const LoginScreen = () => {
  const { isDark } = useTheme();
  const navigation = useNavigation();
  const { t } = useTranslation();
  const { login } = useAuthStore();

  const [email, setEmail] = useState('lam@example.com');
  const [password, setPassword] = useState('123456');
  const [isSecure, setIsSecure] = useState(true);
  const [remember, setRemember] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const topPadding = 44;
  const topHeaderHeight = SCREEN_HEIGHT * 0.35 + topPadding;

  // Entry animation
  const cardAnim = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.timing(cardAnim, {
      toValue: 1,
      duration: 500,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: Platform.OS !== 'web',
    }).start();
  }, [cardAnim]);

  const handleLogin = useCallback(() => {
    const newErrors = {};
    if (!email.trim()) newErrors.email = t('home.enterEmail');
    else if (!isValidEmail(email)) newErrors.email = t('home.invalidEmail');
    if (!password) newErrors.password = t('home.enterPassword');
    else if (!isValidPassword(password)) newErrors.password = t('home.passwordMin');

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setErrors({});
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      login(userMock);
      showSuccess(t('home.loginSuccess'));
      navigation.reset({
        index: 0,
        routes: [{ name: Routes.LoginSuccessVideo }],
      });
    }, 800);
  }, [email, password, login, navigation, t]);

  const handleGoogleLogin = useCallback(() => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      login(userMock);
      showSuccess(t('home.googleLoginSuccess'));
      navigation.reset({
        index: 0,
        routes: [{ name: Routes.LoginSuccessVideo }],
      });
    }, 600);
  }, [login, navigation, t]);

  const cardTranslateY = cardAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [40, 0],
  });

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      style={styles.container}
    >
      <StatusBar barStyle={isDark ? 'light-content' : 'dark-content'} />
      <ScrollView
        contentContainerStyle={{ flexGrow: 1 }}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        {/* Top gradient header */}
        <View style={styles.headerWrap}>
          <LinearGradient
            colors={
              isDark
                ? ['#0E1611', '#142017', '#1B2E21']
                : ['#FFFFFF', '#F5FCF4', '#C7EFC2', '#86D978']
            }
            stops={isDark ? [0.0, 0.5, 1.0] : [0.0, 0.3, 0.7, 1.0]}
            start={{ x: 0.5, y: 0 }}
            end={{ x: 0.5, y: 1 }}
            style={[StyleSheet.absoluteFillObject, { height: topHeaderHeight + 60 }]}
          />
          <View style={[styles.mascotWrap, { top: topPadding + 55, height: topHeaderHeight - 35 }]}>
            <Image
              source={require('../../../../assets/images/mascot_login.png')}
              style={{ width: 260, height: '100%' }}
              resizeMode="contain"
            />
          </View>
          <View style={[styles.topBar, { top: topPadding + 12, left: 16 }]}>
            <Pressable
              onPress={() => navigation.goBack()}
              style={styles.backRow}
            >
              <ChevronLeft
                color={isDark ? '#FFFFFF' : AppColors.textPrimary}
                size={18}
              />
              <Text style={[styles.brand, { fontSize: sp(26), marginLeft: 4 }]}>
                <Text style={{ color: isDark ? '#FFFFFF' : AppColors.textPrimary }}>Fri</Text>
                <Text style={{ color: isDark ? AppColors.primaryLight : AppColors.primary }}>ggy</Text>
              </Text>
            </Pressable>
          </View>
        </View>

        {/* Card bottom */}
        <Animated.View
          style={[
            styles.card,
            {
              marginTop: topHeaderHeight,
              backgroundColor: isDark ? '#0E1611' : '#FFFFFF',
              opacity: cardAnim,
              transform: [{ translateY: cardTranslateY }],
            },
          ]}
        >
          <Text
            style={[
              styles.title,
              {
                color: isDark ? '#FFFFFF' : AppColors.textPrimary,
                fontSize: sp(30),
              },
            ]}
          >
            {t('home.welcome')}
          </Text>

          <View style={{ marginTop: 18 }}>
            <CustomTextField
              placeholder={t('home.email')}
              value={email}
              onChangeText={setEmail}
              keyboardType="email-address"
              error={errors.email}
              prefixIcon={(props) => <Mail {...props} color={isDark ? AppColors.primaryLight : '#8C9890'} size={22} />}
            />
          </View>
          <View style={{ marginTop: 12 }}>
            <CustomTextField
              placeholder={t('home.password')}
              value={password}
              onChangeText={setPassword}
              secureTextEntry={isSecure}
              error={errors.password}
              prefixIcon={(props) => <Lock {...props} color={isDark ? AppColors.primaryLight : '#8C9890'} size={22} />}
              suffixIcon={
                <Pressable onPress={() => setIsSecure(!isSecure)} hitSlop={8}>
                  {isSecure ? (
                    <EyeOff color={AppColors.hintText} size={22} />
                  ) : (
                    <Eye color={AppColors.hintText} size={22} />
                  )}
                </Pressable>
              }
            />
          </View>

          <View style={styles.optionsRow}>
            <CustomCheckbox
              checked={remember}
              onChange={() => setRemember(!remember)}
              label={t('home.rememberMe')}
            />
            <Pressable onPress={() => navigation.navigate(Routes.ForgotPassword)}>
              <Text
                style={[
                  styles.forgotText,
                  { color: isDark ? AppColors.primaryLight : AppColors.primary, fontSize: sp(14) },
                ]}
              >
                {t('home.forgotPassword')}
              </Text>
            </Pressable>
          </View>

          <View style={{ marginTop: 20 }}>
            <CustomButton
              title={t('home.login')}
              onPress={handleLogin}
              loading={isLoading}
              variant="primary"
              height={54}
            />
          </View>

          <View style={{ marginTop: 20 }}>
            <CustomDivider text={t('home.orContinueWith')} />
          </View>

          <View style={{ marginTop: 18 }}>
            <SocialButton type="google" onPress={handleGoogleLogin} />
          </View>

          <View style={styles.footer}>
            <Text
              style={[
                styles.footerText,
                { color: isDark ? AppColors.hintText : '#6B786F', fontSize: sp(14) },
              ]}
            >
              {t('home.noAccount')}
            </Text>
            <Pressable onPress={() => navigation.navigate(Routes.Register)}>
              <Text
                style={[
                  styles.footerLink,
                  { color: isDark ? AppColors.primaryLight : AppColors.primary, fontSize: sp(14) },
                ]}
              >
                {t('home.register')}
              </Text>
            </Pressable>
          </View>

          <View style={{ height: 60 }} />
        </Animated.View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  headerWrap: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '50%',
    overflow: 'visible',
  },
  mascotWrap: {
    position: 'absolute',
    right: 0,
    width: 260,
  },
  topBar: {
    position: 'absolute',
    flexDirection: 'row',
    alignItems: 'center',
  },
  backRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 8,
    paddingVertical: 8,
  },
  brand: {
    fontFamily: FontFamily.black,
    fontWeight: FontWeights.black,
    letterSpacing: 0.5,
  },
  card: {
    width: '100%',
    borderTopLeftRadius: 36,
    borderTopRightRadius: 36,
    paddingHorizontal: 28,
    paddingTop: 28,
    paddingBottom: 24,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -6 },
    shadowOpacity: 0.12,
    shadowRadius: 16,
    elevation: 8,
  },
  title: {
    fontFamily: FontFamily.black,
    fontWeight: FontWeights.black,
    letterSpacing: -0.5,
  },
  optionsRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 12,
  },
  forgotText: {
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
  },
  footer: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: 24,
  },
  footerText: {
    fontFamily: FontFamily.regular,
  },
  footerLink: {
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
    marginLeft: 4,
  },
});

import React, { useEffect, useRef } from 'react';
import { View, Text, StyleSheet, StatusBar } from 'react-native';
import { VideoView, useVideoPlayer } from 'expo-video';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontWeights, FontFamily } from '../../theme/typography';
import { useNavigation } from '@react-navigation/native';
import { useAuthStore } from '../../../shared/stores/useAuthStore';
import loadingVideo from '../../../../assets/videos/loading_login.mp4';

export const LoginSuccessVideoScreen = () => {
  const { isDark } = useTheme();
  const navigation = useNavigation();
  const videoRef = useRef(null);
  const { isOnboarded, completeOnboarding } = useAuthStore();

  const player = useVideoPlayer(loadingVideo, (p) => {
    p.loop = true;
    p.muted = true;
    p.play();
  });

  useEffect(() => {
    const t = setTimeout(() => {
      // After login success, RootNavigator will re-render based on
      // isAuthenticated && isOnboarded state.
      // If !isOnboarded ΓåÆ OnboardingFlow
      // If isOnboarded ΓåÆ MainFlow
      // We reset to AuthFlow which will be replaced immediately by RootNavigator
      // because isAuthenticated is now true.
      navigation.getParent()?.reset({
        index: 0,
        routes: [{ name: 'AuthFlow' }],
      });
    }, 3000);
    return () => clearTimeout(t);
  }, [isOnboarded, navigation]);

  return (
    <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
      <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />
      {player && (
        <VideoView
          ref={videoRef}
          player={player}
          style={StyleSheet.absoluteFillObject}
          contentFit="cover"
          nativeControls={false}
        />
      )}
      <View style={styles.textOverlay}>
        <Text style={[styles.text, { color: '#FFFFFF', fontSize: sp(22) }]}>
          ─É─âng nhß║¡p th├ánh c├┤ng
        </Text>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  textOverlay: {
    position: 'absolute',
    bottom: 80,
    left: 0,
    right: 0,
    alignItems: 'center',
  },
  text: {
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
    textShadowColor: 'rgba(0,0,0,0.4)',
    textShadowOffset: { width: 0, height: 2 },
    textShadowRadius: 4,
  },
});

