                styles.footerLink,
                { color: isDark ? AppColors.primaryLight : '#008435', fontSize: sp(14) },
              ]}
            >
              {t('auth.register')}
            </Text>
          </Pressable>
        </View>
      </View>
    </View>
  );
};

