import React, { useEffect, useRef } from 'react';
import { View, Text, StyleSheet, Animated, Easing, Platform } from 'react-native';
import { VideoView, useVideoPlayer } from 'expo-video';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontWeights, FontFamily } from '../../theme/typography';
import loadingVideo from '../../../../assets/videos/loading_login.mp4';

export const InitialLoadingScreen = () => {
  const { isDark } = useTheme();
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const videoRef = useRef(null);

  const player = useVideoPlayer(loadingVideo, (p) => {
    p.loop = true;
    p.muted = true;
    p.play();
  });

  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 600,
      useNativeDriver: Platform.OS !== 'web',
      easing: Easing.out(Easing.cubic),
    }).start();
  }, []);

  return (
    <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
      {player && (
        <VideoView
          ref={videoRef}
          player={player}
          style={StyleSheet.absoluteFill}
          contentFit="cover"
          nativeControls={false}
        />
      )}
      <Animated.View style={[styles.overlay, { opacity: fadeAnim }]}>
        <Text style={[styles.title, { color: isDark ? '#FFFFFF' : AppColors.textPrimary, fontSize: sp(28) }]}>
          <Text style={{ color: isDark ? '#FFFFFF' : AppColors.textPrimary }}>Fri</Text>
          <Text style={{ color: isDark ? AppColors.primaryLight : AppColors.primary }}>ggy</Text>
        </Text>
        <Text style={[styles.subtitle, { color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary, fontSize: sp(13) }]}>
          ─Éang tß║úi...
        </Text>
      </Animated.View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  overlay: {
    position: 'absolute',
    bottom: 60,
    alignItems: 'center',
  },
  title: {
    fontFamily: FontFamily.black,
    fontWeight: FontWeights.black,
    letterSpacing: 1.2,
  },
  subtitle: {
    marginTop: 6,
    fontFamily: FontFamily.medium,
    fontWeight: FontWeights.medium,
  },
});

/**
 * AllAvailableItemsScreen
 *
 * Redesigned (Sprint 8):
 * - D├╣ng FridgeListScreen (config-driven) - giß║úm tß╗½ 250 d├▓ng ΓåÆ 50 d├▓ng
 * - Tß║Ñt cß║ú logic filter/sort/search ─æ╞░ß╗úc config h├│a
 */

import React from 'react';
import { FridgeListScreen } from './FridgeListScreen';

const CATEGORY_KEYS = {
  ALL: 'all',
  VEGETABLE: 'vegetable',
  MEAT: 'meat',
  DAIRY: 'dairy',
  FRUIT: 'fruit',
  OTHER: 'other',
};

const getDaysToExpiry = (expiryDate) => {
  const expiry = new Date(expiryDate);
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  expiry.setHours(0, 0, 0, 0);
  return Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
};

const SORT_OPTIONS = {
  EXPIRY_ASC: 'expiry_asc',
  EXPIRY_DESC: 'expiry_desc',
  NAME_ASC: 'name_asc',
  NAME_DESC: 'name_desc',
};

const AVAILABLE_CONFIG = {
  titleKey: 'home.availableIngredients',
  baseFilter: (item) => {
    const days = getDaysToExpiry(item.expiryDate);
    return item.status !== 'expired' && days >= 0;
  },
  statusChips: [
    { key: 'all', labelKey: 'home.all', color: undefined },
    { key: 'fresh', labelKey: 'home.filterFresh', color: '#4CAF50' },
    { key: 'expiring', labelKey: 'home.filterExpiring', color: '#FF9800' },
  ],
  statusFilterDefault: 'all',
  statusFilterFn: (item, filterKey) => {
    if (filterKey === 'all') return true;
    return item.status === filterKey;
  },
  categoryChips: [
    { key: 'all', labelKey: 'home.categoryAll' },
    { key: 'vegetable', labelKey: 'home.categoryVegetable', color: '#4CAF50' },
    { key: 'meat', labelKey: 'home.categoryMeat', color: '#E57373' },
    { key: 'dairy', labelKey: 'home.categoryDairy', color: '#FFB300' },
  ],
  categoryFilterDefault: 'all',
  sortOptions: SORT_OPTIONS,
  sortOptionsArray: [
    { key: SORT_OPTIONS.EXPIRY_ASC, labelKey: 'home.sortExpiryAsc' },
    { key: SORT_OPTIONS.EXPIRY_DESC, labelKey: 'home.sortExpiryDesc' },
    { key: SORT_OPTIONS.NAME_ASC, labelKey: 'home.sortNameAsc' },
    { key: SORT_OPTIONS.NAME_DESC, labelKey: 'home.sortNameDesc' },
  ],
  defaultSort: SORT_OPTIONS.EXPIRY_ASC,
  emptyEmoji: '≡ƒÑ¼',
  emptyTitleKey: 'home.noResults',
  emptyHintKey: 'home.noResultsHint',
};

export const AllAvailableItemsScreen = () => {
  return <FridgeListScreen config={AVAILABLE_CONFIG} />;
};

/**
 * FridgeListScreen
 *
 * Generic config-driven screen cho AllAvailableItemsScreen + AllExpiredItemsScreen.
 * - Loß║íi bß╗Å duplicate logic (~300 d├▓ng)
 * - Config truyß╗ün v├áo quyß║┐t ─æß╗ïnh filter/sort/title/empty state
 *
 * Sau n├áy AllAvailableItemsScreen v├á AllExpiredItemsScreen chß╗ë cß║ºn pass config.
 */

import React, { useState, useMemo, useCallback } from 'react';
import { View, Text, StyleSheet, FlatList } from 'react-native';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontFamily, FontWeights } from '../../theme/typography';
import { useTranslation } from 'react-i18next';
import { useNavigation } from '@react-navigation/native';
import { FriggyAppBar } from '../../components/navigation/FriggyAppBar';
import { useFridgeItems } from '../../hooks/useServiceHooks';
import { FridgeItem } from '../../components/fridge/FridgeItem';
import { SearchBar } from '../../components/common/SearchBar';
import { FilterChips } from '../../components/common/FilterChips';
import { EmptyState } from '../../components/common/EmptyState';
import { ErrorState } from '../../components/common/ErrorState';
import { Skeleton } from '../../components/common/Skeleton';
import { SortMenu } from '../../components/common/SortMenu';

const getDaysToExpiry = (expiryDate) => {
  const expiry = new Date(expiryDate);
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  expiry.setHours(0, 0, 0, 0);
  return Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
};

const sortItems = (items, sortKey, sortOptions) => {
  return [...items].sort((a, b) => {
    switch (sortKey) {
      case sortOptions.EXPIRY_ASC:
        return new Date(a.expiryDate) - new Date(b.expiryDate);
      case sortOptions.EXPIRY_DESC:
        return new Date(b.expiryDate) - new Date(a.expiryDate);
      case sortOptions.NAME_ASC:
        return a.name.localeCompare(b.name);
      case sortOptions.NAME_DESC:
        return b.name.localeCompare(a.name);
      case sortOptions.URGENT_FIRST: {
        const aDays = getDaysToExpiry(a.expiryDate);
        const bDays = getDaysToExpiry(b.expiryDate);
        if (aDays < 0 && bDays >= 0) return -1;
        if (aDays >= 0 && bDays < 0) return 1;
        return aDays - bDays;
      }
      default:
        return 0;
    }
  });
};

export const FridgeListScreen = ({
  config,
}) => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const navigation = useNavigation();
  const { data: items, loading, error, refetch } = useFridgeItems();

  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState(config.statusFilterDefault || 'all');
  const [categoryFilter, setCategoryFilter] = useState(config.categoryFilterDefault || 'all');
  const [sort, setSort] = useState(config.defaultSort);

  // B╞░ß╗¢c 1: Lß╗ìc theo ─æiß╗üu kiß╗çn ti├¬n quyß║┐t (chß╗ë fresh+expiring, hoß║╖c expiring+expired)
  const baseItems = useMemo(() => {
    if (!items) return [];
    return items.filter(config.baseFilter);
  }, [items, config.baseFilter]);

  // B╞░ß╗¢c 2: Filter theo status
  const statusFiltered = useMemo(() => {
    if (statusFilter === 'all') return baseItems;
    if (typeof config.statusFilterFn === 'function') {
      return baseItems.filter((it) => config.statusFilterFn(it, statusFilter));
    }
    return baseItems.filter((it) => it.status === statusFilter);
  }, [baseItems, statusFilter, config]);

  // B╞░ß╗¢c 3: Filter theo category
  const categoryFiltered = useMemo(() => {
    if (categoryFilter === 'all') return statusFiltered;
    return statusFiltered.filter((it) => it.category === categoryFilter);
  }, [statusFiltered, categoryFilter]);

  // B╞░ß╗¢c 4: Search
  const searched = useMemo(() => {
    if (!search.trim()) return categoryFiltered;
    const q = search.toLowerCase().trim();
    return categoryFiltered.filter((it) => it.name.toLowerCase().includes(q));
  }, [categoryFiltered, search]);

  // B╞░ß╗¢c 5: Sort
  const filteredItems = useMemo(
    () => sortItems(searched, sort, config.sortOptions),
    [searched, sort, config.sortOptions],
  );

  // Counts
  const counts = useMemo(() => {
    const c = { all: baseItems.length };
    config.statusChips.forEach((chip) => {
      c[chip.key] = baseItems.filter((it) => config.statusFilterFn(it, chip.key)).length;
    });
    if (config.categoryChips) {
      config.categoryChips.forEach((chip) => {
        if (chip.key === 'all') return;
        c[chip.key] = baseItems.filter((it) => it.category === chip.key).length;
      });
    }
    return c;
  }, [baseItems, config]);

  const statusChips = useMemo(
    () =>
      config.statusChips.map((chip) => ({
        ...chip,
        label: t(chip.labelKey, { defaultValue: chip.labelKey }),
        count: counts[chip.key] || 0,
      })),
    [config.statusChips, counts, t],
  );

  const categoryChips = useMemo(
    () =>
      config.categoryChips
        ? config.categoryChips.map((chip) => ({
            ...chip,
            label: t(chip.labelKey, { defaultValue: chip.labelKey }),
            count: counts[chip.key] || 0,
          }))
        : null,
    [config.categoryChips, counts, t],
  );

  const sortOptions = useMemo(
    () =>
      config.sortOptionsArray.map((opt) => ({
        key: opt.key,
        label: t(opt.labelKey, { defaultValue: opt.labelKey }),
      })),
    [config.sortOptionsArray, t],
  );

  const currentSortLabel = useMemo(
    () => sortOptions.find((o) => o.key === sort)?.label || '',
    [sortOptions, sort],
  );

  // Loading state
  if (loading && !items) {
    return (
      <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
        <FriggyAppBar showBackButton onBackTap={() => navigation.goBack()} />
        <View style={styles.header}>
          <Text
            style={[
              styles.title,
              { color: isDark ? '#FFFFFF' : AppColors.textPrimary, fontSize: sp(22) },
            ]}
          >
            {t(config.titleKey)}
          </Text>
        </View>
        <View style={{ paddingHorizontal: sp(20), gap: sp(10) }}>
          <Skeleton width="100%" height={sp(42)} borderRadius={sp(12)} style={{ marginBottom: sp(8) }} />
          {[0, 1, 2, 3, 4].map((i) => (
            <Skeleton key={i} width="100%" height={sp(72)} borderRadius={sp(14)} />
          ))}
        </View>
      </View>
    );
  }

  // Error state
  if (error && !items) {
    return (
      <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
        <FriggyAppBar showBackButton onBackTap={() => navigation.goBack()} />
        <ErrorState onRetry={refetch} style={{ marginTop: sp(40) }} />
      </View>
    );
  }

  const hasFilters = !!search || statusFilter !== 'all' || (categoryFilter !== 'all' && categoryChips);

  return (
    <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
      <FriggyAppBar showBackButton onBackTap={() => navigation.goBack()} />

      <View style={styles.header}>
        <View style={{ flex: 1 }}>
          <Text
            style={[
              styles.title,
              { color: isDark ? '#FFFFFF' : AppColors.textPrimary, fontSize: sp(22) },
            ]}
          >
            {t(config.titleKey)}
          </Text>
          <Text
            style={[
              styles.subtitle,
              { color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary, fontSize: sp(13) },
            ]}
          >
            {filteredItems.length > 0
              ? t('home.resultCount', { count: filteredItems.length })
              : t('home.resultCountEmpty')}
          </Text>
        </View>
        {config.sortOptionsArray ? (
          <SortMenu
            current={sort}
            options={sortOptions}
            onSelect={setSort}
            label={currentSortLabel}
          />
        ) : null}
      </View>

      <View style={{ paddingHorizontal: sp(20), marginBottom: sp(12) }}>
        <SearchBar
          value={search}
          onChangeText={setSearch}
          placeholder={t('home.searchHint')}
        />
      </View>

      <FilterChips
        options={statusChips}
        selectedKey={statusFilter}
        onSelect={setStatusFilter}
        style={{ marginBottom: sp(8) }}
      />

      {categoryChips ? (
        <FilterChips
          options={categoryChips}
          selectedKey={categoryFilter}
          onSelect={setCategoryFilter}
          style={{ marginBottom: sp(12) }}
        />
      ) : (
        <View style={{ height: sp(4) }} />
      )}

      <FlatList
        data={filteredItems}
        keyExtractor={(it) => it.id}
        contentContainerStyle={{ paddingHorizontal: sp(20), paddingBottom: sp(24) }}
        ItemSeparatorComponent={() => <View style={{ height: sp(10) }} />}
        ListEmptyComponent={
          baseItems.length === 0 ? (
            <EmptyState
              emoji={config.emptyEmoji}
              title={t(config.emptyTitleKey, { defaultValue: config.emptyTitleKey })}
              hint={t(config.emptyHintKey, { defaultValue: config.emptyHintKey })}
            />
          ) : hasFilters ? (
            <EmptyState
              emoji="≡ƒöì"
              title={t('home.noResults')}
              hint={t('home.noResultsHint')}
            />
          ) : null
        }
        renderItem={({ item }) => <FridgeItem item={item} />}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    paddingHorizontal: sp(20),
    paddingTop: sp(8),
    paddingBottom: sp(12),
    gap: sp(8),
  },
  title: {
    fontFamily: FontFamily.black,
    fontWeight: FontWeights.black,
  },
  subtitle: {
    fontFamily: FontFamily.medium,
    fontWeight: FontWeights.medium,
    marginTop: sp(4),
  },
});

