export const UserAllergiesScreen = () => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const navigation = useNavigation();
  const [allergies, setAllergies] = useState(allergiesMock.allergies);

  const remove = useCallback(
    (id) => {
      Alert.alert(t('home.removeAllergy'), t('home.removeMemberConfirm'), [
        { text: t('home.cancel'), style: 'cancel' },
        {
          text: t('home.removeAllergy'),
          style: 'destructive',
          onPress: () => setAllergies(allergies.filter((a) => a.id !== id)),
        },
      ]);
    },
    [allergies, t],
  );

  const cycleSeverity = useCallback(
    (id) => {
      setAllergies(
        allergies.map((a) => {
          if (a.id !== id) return a;
          const order = ['low', 'medium', 'high'];
          const idx = order.indexOf(a.severity);
          return { ...a, severity: order[(idx + 1) % order.length] };
        }),
      );
    },
    [allergies],
  );

  const add = useCallback(() => {
    showInfo('Mß╗ƒ dialog th├¬m dß╗ï ß╗⌐ng (mock)');
    setAllergies([
      ...allergies,
      { id: String(Date.now()), name: `Dß╗ï ß╗⌐ng mß╗¢i ${allergies.length + 1}`, severity: 'medium' },
    ]);
  }, [allergies]);

  return (
    <View style={[styles.container, { backgroundColor: isDark ? '#0E1611' : '#FFFFFF' }]}>
      <FriggyAppBar showBackButton onBackTap={() => navigation.goBack()} />
      <ScrollView contentContainerStyle={styles.scroll} showsVerticalScrollIndicator={false}>
