import React, { createContext, useContext, useEffect, useState } from 'react';
import { useColorScheme } from 'react-native';
import { AppColors } from './colors';
import { useThemeStore } from '../../shared/stores/useThemeStore';

const ThemeContext = createContext({
  isDark: false,
  colors: AppColors,
  themeMode: 'system',
  toggleTheme: () => {},
  setTheme: () => {},
});

export const ThemeProvider = ({ children }) => {
  const systemScheme = useColorScheme();
  const { themeMode, setThemeMode, initTheme } = useThemeStore();
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    initTheme();
  }, []);

  useEffect(() => {
    if (themeMode === 'system') {
      setIsDark(systemScheme === 'dark');
    } else {
      setIsDark(themeMode === 'dark');
    }
  }, [themeMode, systemScheme]);

  const value = {
    isDark,
    colors: AppColors,
    themeMode,
    toggleTheme: () => setThemeMode(isDark ? 'light' : 'dark'),
    setTheme: setThemeMode,
  };

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
};

export const useTheme = () => useContext(ThemeContext);

import React, { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useLanguageStore } from '../stores/useLanguageStore';

export const LanguageBridge = ({ children }) => {
  const { i18n } = useTranslation();
  const { locale, initLocale } = useLanguageStore();

  useEffect(() => {
    initLocale();
  }, []);

  useEffect(() => {
    if (locale && i18n.language !== locale) {
      i18n.changeLanguage(locale);
    }
  }, [locale, i18n]);

  return children;
};

import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import vi from './locales/vi.json';
import en from './locales/en.json';

i18n.use(initReactI18next).init({
  compatibilityJSON: 'v4',
  resources: {
    vi: { translation: vi },
    en: { translation: en },
  },
  lng: 'vi', // Mß║╖c ─æß╗ïnh tiß║┐ng Viß╗çt
  fallbackLng: 'vi',
  defaultNS: 'translation',
  interpolation: {
    escapeValue: false,
  },
  react: {
    useSuspense: false,
  },
});

export default i18n;

// Map Auth state
import { create } from 'zustand';

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
    delete: (k) => {
      delete memStore[k];
    },
  };
}

const STORAGE_USER = 'user';
const STORAGE_ONBOARDED = 'isOnboarded';

export const useAuthStore = create((set) => ({
  user: null,
  isAuthenticated: false,
  isOnboarded: false,
  initAuth: () => {
    try {
      const saved = mmkv.getString(STORAGE_USER);
      const savedOnboarded = mmkv.getString(STORAGE_ONBOARDED);
      if (saved) {
        const user = JSON.parse(saved);
        set({
          user,
          isAuthenticated: true,
          isOnboarded: savedOnboarded === 'true',
        });
      }
    } catch (e) {
      // ignore
    }
  },
  login: (user) => {
    try {
      mmkv.set(STORAGE_USER, JSON.stringify(user));
    } catch (e) {
      // ignore
    }
    set({ user, isAuthenticated: true });
  },
  logout: () => {
    try {
      mmkv.delete(STORAGE_USER);
      mmkv.delete(STORAGE_ONBOARDED);
    } catch (e) {
      // ignore
    }
    set({ user: null, isAuthenticated: false, isOnboarded: false });
  },
  completeOnboarding: () => {
    try {
      mmkv.set(STORAGE_ONBOARDED, 'true');
    } catch (e) {
      // ignore
    }
    set({ isOnboarded: true });
  },
  setUser: (user) => set({ user }),
}));

// Map LanguageProvider trong Flutter
import { create } from 'zustand';
import { getLocales } from 'expo-localization';

const STORAGE_KEY = 'language';

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
  };
}

const detectInitialLocale = () => {
  try {
    const locales = getLocales();
    if (locales && locales[0] && locales[0].languageCode === 'en') {
      return 'en';
    }
  } catch (e) {
    // ignore
  }
  return 'vi'; // Default Vietnamese
};

export const useLanguageStore = create((set) => ({
  locale: detectInitialLocale(),
  initLocale: () => {
    try {
      const saved = mmkv.getString(STORAGE_KEY);
      if (saved) {
        set({ locale: saved });
      }
    } catch (e) {
      // ignore
    }
  },
  setLocale: (lang) => {
    try {
      mmkv.set(STORAGE_KEY, lang);
    } catch (e) {
      // ignore
    }
    set({ locale: lang });
  },
  toggleLocale: () => {
    set((state) => {
      const next = state.locale === 'vi' ? 'en' : 'vi';
      try {
        mmkv.set(STORAGE_KEY, next);
      } catch (e) {
        // ignore
      }
      return { locale: next };
    });
  },
}));

// Map ThemeProvider trong Flutter
import { create } from 'zustand';
import { Appearance } from 'react-native';

const STORAGE_KEY = 'themeMode';

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  // MMKV not available - fallback to in-memory
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
  };
}

export const useThemeStore = create((set) => ({
  themeMode: 'system', // 'light' | 'dark' | 'system'
  initTheme: () => {
    try {
      const saved = mmkv.getString(STORAGE_KEY);
      if (saved) {
        set({ themeMode: saved });
      } else {
        const sys = Appearance.getColorScheme();
        set({ themeMode: sys === 'dark' ? 'dark' : 'light' });
      }
    } catch (e) {
      // fallback
    }
  },
  setThemeMode: (mode) => {
    try {
      mmkv.set(STORAGE_KEY, mode);
    } catch (e) {
      // ignore
    }
    set({ themeMode: mode });
  },
}));
